('ex_bb_back_squat','barbell-back-squat','Barbell Back Squat','strength','["quads", "glutes"]','["hamstrings", "core", "lower_back"]','["strength", "legs", "barbell", "gym", "no_floor", "loads_knee", "loads_lower_back"]','["barbell", "squat_rack"]','{"steps": ["Set the bar at upper-chest height in the rack. Step under it, bar resting across your upper back \u2014 not your neck.", "Brace, stand it up, step back two steps.", "Sit down and back until your thighs reach parallel.", "Drive through the whole foot to stand."], "cues": ["Knees track over the toes", "Chest stays proud out of the hole", "\ud83d\udca1 Always use the safety pins \u2014 set them just below your bottom position"]}','{"supports": ["weight", "reps", "sets", "tempo"]}',1,'global',1789301000000,1789301000000),
